// 話者が男性に偏っていたため、女性が言っても自然な行（Jev で判定）の一部を
// ครับ→ค่ะ/คะ、ผม→ฉัน に書き換え、テーマごとに男女をおおむね揃えた。
// 推し活（ライブ遠征・ファン同士の交流・推しの誕生日企画・推しに伝えたい言葉・推しのグッズ）は、
// ファンの vlog・ポッドキャストの音声を Cloud Speech-to-Text（Chirp）で文字起こしした行と、
// Wisesight Sentiment コーパス（CC0）の SNS 投稿から選んだ。言いよどみ・繰り返しを詰めた行がある。
// 文を足したら scripts/build_shot_embeddings.py を流して GCS に上げる（場面の選出に使う）。
